import React, { useState, useEffect } from 'react'
import AstroBackground from '../UI/AstroBackground'
import { Link } from 'react-router-dom'
import { doc, getDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'

const LotusIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 22c-2.4 0-4.8-.9-6.6-2.6A9.95 9.95 0 0 1 2 12c0-3.6 2.3-6.8 5.6-8.2 1.5-.6 3.1-.7 4.7-.3.9.2 1.8.6 2.6 1.1.8-.5 1.7-.9 2.6-1.1 1.6-.4 3.2-.3 4.7.3 3.3 1.4 5.6 4.6 5.6 8.2 0 2.6-.9 5-2.6 6.8C18.6 21 15.3 22 12 22Z" />
        <path d="M12 12a10 10 0 1 0 0 10 10 10 0 1 0 0-10Z" />
        <path d="M12 12v10" />
    </svg>
)

const PointIcon1 = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z" />
        <path d="M7 14s2-2 5-2 5 2 5 2" />
        <path d="M12 12a2 2 0 1 0 0-4 2 2 0 0 0 0 4z" />
    </svg>
)

const PointIcon2 = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
        <circle cx="9" cy="7" r="4" />
        <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
        <path d="M16 3.13a4 4 0 0 1 0 7.75" />
    </svg>
)

const PointIcon3 = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1 0-5H20" />
    </svg>
)

const DEFAULT_CONFIG = {
    eyebrow: 'ABOUT ANITA DOVAL',
    heading: 'Understanding the\nperson beyond the chart.',
    description: 'Anita Doval\'s journey has been shaped by years of study, practice and real-life experience. Her approach combines the wisdom of astrology and Vastu with a deep understanding of human nature and spiritual principles.',
    portrait: { url: '/images/post1.jpg', position: 'center center', alt: 'Anita Doval' },
    badge: {
        enabled: true,
        label: 'Years of',
        mainText: 'Guidance & Practice',
    },
    points: [
        { text: 'Holistic and practical approach', enabled: true },
        { text: 'Personalised consultations', enabled: true },
        { text: 'Guidance rooted in knowledge and experience', enabled: true }
    ],
    cta: {
        enabled: true,
        text: 'Discover Her Journey',
        url: '/about'
    },
    quote: {
        enabled: true,
        text: 'Every chart tells\na story, but every\nperson\'s journey\nis unique.',
        decorationEnabled: true
    }
}

const QuoteDecoration = () => (
    <div className="flex items-center justify-center gap-3 mt-6 opacity-70">
        <div className="h-[1px] w-[30px] bg-[var(--gold-400)]"></div>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="var(--gold-400)">
            <path d="M12 2L2 12l10 10 10-10L12 2z" />
        </svg>
        <div className="h-[1px] w-[30px] bg-[var(--gold-400)]"></div>
    </div>
)

const AboutPreview = () => {
    const [config, setConfig] = useState(DEFAULT_CONFIG)

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                // If the user hooks this up to admin panel, we fetch from a document
                const docRef = doc(db, 'services', 'about_config')
                const docSnap = await getDoc(docRef)
                if (docSnap.exists()) {
                    // merge cautiously to not break structure
                    setConfig(prev => ({ ...prev, ...docSnap.data() }))
                }
            } catch (err) {
                // Silently fallback to DEFAULT_CONFIG
            }
        }
        fetchConfig()
    }, [])

    const headingLines = config.heading?.split('\\n').map(l => l.trim()).filter(Boolean) || []
    if (headingLines.length === 0 && config.heading) {
        headingLines.push(...config.heading.split('\n'))
    }

    const quoteLines = config.quote?.text?.split('\\n').map(l => l.trim()).filter(Boolean) || []
    if (quoteLines.length === 0 && config.quote?.text) {
        quoteLines.push(...config.quote.text.split('\n'))
    }

    if (config.sectionEnabled === false) {
        return null;
    }
    if (!config.heading && !config.description) {
        return null;
    }

    const sectionStyle = config.background?.url ? {
        backgroundImage: `url(${config.background.url})`,
        backgroundSize: config.background.bgSize || 'cover',
        backgroundRepeat: config.background.bgRepeat || 'no-repeat',
        backgroundPosition: config.background.bgPosition || 'center'
    } : {}

    return (
        <section
            className="relative py-[90px] md:py-[120px] lg:py-[150px] bg-[#FBF8F1] flex justify-center items-center overflow-hidden"
            style={sectionStyle}
        >

            {/* Optional Background Overlay for readability if BG exists */}
            {config.background?.url && (
                <div className="absolute inset-0 bg-[rgba(245,239,228,0)] z-0 pointer-events-none"></div>
            )}

            <AstroBackground />


            <div className="relative z-10 container max-w-[1360px] px-[24px] md:px-[40px] lg:px-[56px] mx-auto">
                <div className="flex flex-col lg:grid lg:grid-cols-12 gap-[50px] lg:gap-[40px] xl:gap-[60px] items-center lg:items-stretch">

                    {/* LEFT COLUMN — IMAGE (Approx 5 cols ~ 41.6%) */}
                    <div className="w-full lg:col-span-5 relative flex-1 flex flex-col justify-center animate-fade-up" style={{ animationDelay: '0.1s', animationFillMode: 'both' }}>
                        <div className="relative w-full aspect-[4/5] md:aspect-square lg:aspect-[4.2/5] rounded-[16px] overflow-hidden shadow-[0_24px_60px_-15px_rgba(45,35,20,0.15)] group cursor-default border border-[#E7DCCB]/50">
                            <img
                                src={config.portrait?.url}
                                alt={config.portrait?.alt}
                                className="w-full h-full object-cover transition-transform duration-[700ms] group-hover:scale-[1.03]"
                                style={{ objectPosition: config.portrait?.position || 'center' }}
                                loading="lazy"
                            />
                            {/* BADGE */}
                            {config.badge?.enabled && (
                                <div className="absolute bottom-[20px] left-[20px] lg:bottom-[32px] lg:left-[-24px] bg-white/95 backdrop-blur-xl border border-white/40 shadow-[0_16px_40px_rgba(45,35,20,0.08)] px-[20px] py-[16px] rounded-[12px] flex items-center gap-[16px] max-w-[260px] z-20">
                                    <div className="text-[#A67828] bg-[#FBF8F1] w-12 h-12 rounded-full flex items-center justify-center shrink-0 border border-[#E7DCCB]/60 shadow-sm">
                                        <LotusIcon />
                                    </div>
                                    <div className="flex flex-col justify-center">
                                        <span className="font-sans text-[11px] md:text-[12px] text-[#8C8378] font-bold tracking-wider uppercase leading-none mb-[4px]">{config.badge?.label}</span>
                                        <span className="font-serif text-[16px] md:text-[18px] font-bold text-[#29251F] leading-[1.1]">{config.badge?.mainText}</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* CENTER COLUMN — CONTENT (Approx 5 cols ~ 41.6%) */}
                    <div className="w-full lg:col-span-5 flex flex-col justify-center animate-fade-in" style={{ animationDelay: '0.2s', animationFillMode: 'both' }}>
                        <p className="font-sans text-[11px] md:text-[12px] font-semibold tracking-[0.2em] uppercase text-[#A67828] mb-[20px]">
                            {config.eyebrow}
                        </p>

                        <h2 className="font-serif font-medium text-[38px] md:text-[48px] lg:text-[56px] leading-[1.05] tracking-[-0.02em] text-[#25221E] mb-[24px] max-w-[540px]">
                            {headingLines.map((line, idx) => (
                                <React.Fragment key={idx}>
                                    {line}{idx !== headingLines.length - 1 && <br />}
                                </React.Fragment>
                            ))}
                        </h2>

                        <p className="font-sans text-[15px] lg:text-[16px] leading-[1.75] text-[#554E46] mb-[32px] max-w-[500px]">
                            {config.description}
                        </p>

                        <div className="flex flex-col gap-[14px] md:gap-[16px] mb-[36px]">
                            {config.points?.[0]?.enabled && (
                                <div className="flex items-center gap-[14px]">
                                    <div className="w-[44px] h-[44px] shrink-0 rounded-full border border-[#E7DCCB] bg-[#FFFDF8] flex items-center justify-center text-[#A67828] shadow-[0_2px_8px_rgba(70,50,25,0.04)]">
                                        <PointIcon1 />
                                    </div>
                                    <span className="font-sans text-[14px] lg:text-[15px] font-medium text-[#403A33] leading-[1.4]">{config.points[0].text}</span>
                                </div>
                            )}
                            {config.points?.[1]?.enabled && (
                                <div className="flex items-center gap-[14px]">
                                    <div className="w-[44px] h-[44px] shrink-0 rounded-full border border-[#E7DCCB] bg-[#FFFDF8] flex items-center justify-center text-[#A67828] shadow-[0_2px_8px_rgba(70,50,25,0.04)]">
                                        <PointIcon2 />
                                    </div>
                                    <span className="font-sans text-[14px] lg:text-[15px] font-medium text-[#403A33] leading-[1.4]">{config.points[1].text}</span>
                                </div>
                            )}
                            {config.points?.[2]?.enabled && (
                                <div className="flex items-center gap-[14px]">
                                    <div className="w-[44px] h-[44px] shrink-0 rounded-full border border-[#E7DCCB] bg-[#FFFDF8] flex items-center justify-center text-[#A67828] shadow-[0_2px_8px_rgba(70,50,25,0.04)]">
                                        <PointIcon3 />
                                    </div>
                                    <span className="font-sans text-[14px] lg:text-[15px] font-medium text-[#403A33] leading-[1.4]">{config.points[2].text}</span>
                                </div>
                            )}
                        </div>

                        {config.cta?.enabled && (
                            <div>
                                <Link
                                    to={config.cta?.url || '#'}
                                    className="inline-flex items-center justify-center gap-[10px] bg-[#a67828] hover:bg-[#8C641C] text-white h-[52px] md:h-[56px] px-[32px] rounded-[6px] font-sans text-[14px] md:text-[15px] font-semibold transition-colors duration-[250ms] w-full md:w-auto shadow-[0_8px_20px_rgba(166,120,40,0.2)]"
                                >
                                    {config.cta?.text}
                                    <span className="text-[18px] leading-none mb-[2px]">&rarr;</span>
                                </Link>
                            </div>
                        )}
                    </div>

                    {/* RIGHT COLUMN — QUOTE (Approx 2 cols ~ 16.6%) */}
                    {config.quote?.enabled && (
                        <div className="w-full lg:col-span-2 flex flex-col justify-start animate-fade-in relative lg:pl-[40px] mt-[40px] md:mt-0 pt-[40px] md:pt-0 border-t md:border-t-0 md:border-l border-[#E7DCCB]/60" style={{ animationDelay: '0.3s', animationFillMode: 'both' }}>
                            <div className="flex flex-col items-center lg:items-start text-center lg:text-left mx-auto lg:mx-0 max-w-[320px] lg:max-w-full lg:mt-[20px]">
                                <span className="font-serif text-[100px] leading-[0.5] text-[#DBC6A3] opacity-[0.5] mb-[30px] self-center lg:self-start lg:-ml-2">
                                    “
                                </span>
                                <p className="font-serif italic text-[24px] md:text-[28px] font-medium leading-[1.3] text-[#74695D] max-w-[240px] mx-auto lg:mx-0">
                                    {quoteLines.map((line, idx) => (
                                        <React.Fragment key={idx}>
                                            {line}{idx !== quoteLines.length - 1 && <br />}
                                        </React.Fragment>
                                    ))}
                                </p>
                                {config.quote?.decorationEnabled && <QuoteDecoration />}
                            </div>
                        </div>
                    )}

                </div>
            </div>
        </section>
    )
}

export default AboutPreview

import React, { useState, useEffect } from 'react'
import { doc, getDoc, setDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'
import { CheckCircle2 } from 'lucide-react'
import Button from '../UI/Button'
import Loading from '../UI/Loading'

const DEFAULT_CONFIG = {
    sectionEnabled: true,
    eyebrow: 'TAKE THE FIRST STEP TOWARDS CLARITY',
    heading: 'Begin Your Consultation',
    description: 'Connect for personalised guidance in astrology, Vastu and spiritual practices.',
    primaryCta: { enabled: true, text: 'Book a Consultation' },
    whatsappCta: { enabled: true, text: 'Connect on WhatsApp' }
}

const CTAManager = () => {
    const [loading, setLoading] = useState(true)
    const [saving, setSaving] = useState(false)
    const [config, setConfig] = useState(DEFAULT_CONFIG)
    const [statusMessage, setStatusMessage] = useState(null)

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'cta_config')
                const snap = await getDoc(docRef)
                if (snap.exists()) {
                    setConfig({ ...DEFAULT_CONFIG, ...snap.data() })
                }
            } catch (err) {
                console.error("Failed to load CTA configuration", err)
            } finally {
                setLoading(false)
            }
        }
        fetchConfig()
    }, [])

    const handleChange = (field, value) => {
        setConfig(prev => ({ ...prev, [field]: value }))
    }

    const handleNestedChange = (parent, field, value) => {
        setConfig(prev => ({
            ...prev,
            [parent]: { ...prev[parent], [field]: value }
        }))
    }

    const handleSave = async () => {
        setSaving(true)
        setStatusMessage(null)
        try {
            await setDoc(doc(db, 'services', 'cta_config'), config)
            setStatusMessage({ type: 'success', text: 'CTA section updated successfully!' })
            setTimeout(() => setStatusMessage(null), 3000)
        } catch (error) {
            setStatusMessage({ type: 'error', text: 'Failed to save changes.' })
        } finally {
            setSaving(false)
        }
    }

    if (loading) return <div className="p-10 flex justify-center"><Loading type="spinner" /></div>

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 mb-2">Bottom CTA Content</h1>
                    <p className="text-gray-600 text-sm">Manage the text and content of the Call to Action banner shown across pages.</p>
                </div>
                <div className="flex items-center gap-4 border border-gray-200 rounded-lg p-2 bg-white shadow-sm">
                    <span className="text-sm font-medium text-gray-700 ml-2">Show Section:</span>
                    <label className="relative inline-flex items-center cursor-pointer mr-2">
                        <input type="checkbox" checked={config.sectionEnabled} onChange={(e) => handleChange('sectionEnabled', e.target.checked)} className="sr-only peer" />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-500"></div>
                    </label>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-100">
                    <h3 className="font-semibold text-lg border-b border-gray-100 pb-4 mb-6">Typography</h3>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Eyebrow</label>
                            <input type="text" value={config.eyebrow} onChange={(e) => handleChange('eyebrow', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 uppercase text-sm" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Heading</label>
                            <input type="text" value={config.heading} onChange={(e) => handleChange('heading', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 font-serif" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                            <textarea value={config.description} onChange={(e) => handleChange('description', e.target.value)} rows={3} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-100">
                    <h3 className="font-semibold text-lg border-b border-gray-100 pb-4 mb-6">Action Buttons</h3>
                    <div className="space-y-6">
                        <div className="p-4 bg-gray-50 border border-gray-100 rounded-xl relative">
                            <div className="absolute top-4 right-4">
                                <input type="checkbox" checked={config.primaryCta.enabled} onChange={(e) => handleNestedChange('primaryCta', 'enabled', e.target.checked)} className="rounded" title="Enable Button" />
                            </div>
                            <h4 className="font-medium text-gray-800 mb-4">Primary Button (Pop-up)</h4>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Button Text</label>
                                <input type="text" value={config.primaryCta.text} onChange={(e) => handleNestedChange('primaryCta', 'text', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                            </div>
                        </div>

                        <div className="p-4 bg-gray-50 border border-gray-100 rounded-xl relative">
                            <div className="absolute top-4 right-4">
                                <input type="checkbox" checked={config.whatsappCta.enabled} onChange={(e) => handleNestedChange('whatsappCta', 'enabled', e.target.checked)} className="rounded" title="Enable Whatsapp" />
                            </div>
                            <h4 className="font-medium text-gray-800 mb-4">WhatsApp Button</h4>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Button Text</label>
                                <input type="text" value={config.whatsappCta.text} onChange={(e) => handleNestedChange('whatsappCta', 'text', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="fixed bottom-0 left-[280px] right-0 bg-white border-t border-gray-200 p-4 px-8 z-40 flex items-center justify-between shadow-[0_-4px_24px_rgba(0,0,0,0.02)]">
                <span className="text-sm text-gray-500 flex items-center gap-2">
                    {statusMessage && statusMessage.type === 'success' && <CheckCircle2 className="w-5 h-5 text-green-500" />}
                    {statusMessage?.text || 'Changes sync directly to Firestore.'}
                </span>
                <Button onClick={handleSave} disabled={saving} className="bg-primary-600 hover:bg-primary-700 text-white min-w-[120px]">
                    {saving ? 'Saving...' : 'Save Changes'}
                </Button>
            </div>
        </div>
    )
}

export default CTAManager

import React, { useState, useEffect } from 'react'
import { doc, getDoc, setDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'
import { Plus, Trash2, CheckCircle2 } from 'lucide-react'
import Button from '../UI/Button'
import Loading from '../UI/Loading'

const DEFAULT_CONFIG = {
    sectionEnabled: true,
    eyebrow: 'HAVE QUESTIONS?',
    heading: 'Frequently \nAsked Questions',
    description: 'Find answers to common questions about our consultations, services and process.',
    buttonText: 'Contact Us',
    buttonUrl: '/contact',
    faqs: [
        { id: 'faq-1', question: 'What can I expect in a consultation?', answer: 'Our consultations provide deep insights into your current life path...' }
    ]
}

const FAQManager = () => {
    const [loading, setLoading] = useState(true)
    const [saving, setSaving] = useState(false)
    const [config, setConfig] = useState(DEFAULT_CONFIG)
    const [statusMessage, setStatusMessage] = useState(null)

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'faq_config')
                const snap = await getDoc(docRef)
                if (snap.exists()) {
                    setConfig({ ...DEFAULT_CONFIG, ...snap.data() })
                }
            } catch (err) {
                console.error("Failed to load FAQ configuration", err)
            } finally {
                setLoading(false)
            }
        }
        fetchConfig()
    }, [])

    const handleChange = (field, value) => setConfig(prev => ({ ...prev, [field]: value }))

    const handleFaqChange = (idx, field, value) => {
        const newFaqs = [...config.faqs]
        newFaqs[idx] = { ...newFaqs[idx], [field]: value }
        handleChange('faqs', newFaqs)
    }

    const addFaq = () => {
        handleChange('faqs', [...config.faqs, { id: `faq-${Date.now()}`, question: 'New Question?', answer: 'Answer here.' }])
    }

    const removeFaq = (idx) => {
        const newFaqs = [...config.faqs]
        newFaqs.splice(idx, 1)
        handleChange('faqs', newFaqs)
    }

    const handleSave = async () => {
        setSaving(true)
        setStatusMessage(null)
        try {
            await setDoc(doc(db, 'services', 'faq_config'), config)
            setStatusMessage({ type: 'success', text: 'FAQ section updated successfully!' })
            setTimeout(() => setStatusMessage(null), 3000)
        } catch (error) {
            setStatusMessage({ type: 'error', text: 'Failed to save changes.' })
        } finally {
            setSaving(false)
        }
    }

    if (loading) return <div className="p-10 flex justify-center"><Loading type="spinner" /></div>

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <div className="flex justify-between items-start">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 mb-2">Frequently Asked Questions</h1>
                    <p className="text-gray-600 text-sm">Manage the questions and answers displayed in the FAQ section.</p>
                </div>
                <div className="flex items-center gap-4 border border-gray-200 rounded-lg p-2 bg-white shadow-sm">
                    <span className="text-sm font-medium text-gray-700 ml-2">Show Section:</span>
                    <label className="relative inline-flex items-center cursor-pointer mr-2">
                        <input type="checkbox" checked={config.sectionEnabled} onChange={(e) => handleChange('sectionEnabled', e.target.checked)} className="sr-only peer" />
                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-500"></div>
                    </label>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-4 space-y-6">
                    <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-100">
                        <h3 className="font-semibold text-lg border-b border-gray-100 pb-4 mb-6">Text Content</h3>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Eyebrow</label>
                                <input type="text" value={config.eyebrow} onChange={(e) => handleChange('eyebrow', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Heading</label>
                                <textarea value={config.heading} onChange={(e) => handleChange('heading', e.target.value)} rows={2} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 font-serif" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                                <textarea value={config.description} onChange={(e) => handleChange('description', e.target.value)} rows={3} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Button Text</label>
                                <input type="text" value={config.buttonText} onChange={(e) => handleChange('buttonText', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-8 space-y-6">
                    <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-100">
                        <div className="flex justify-between items-center border-b border-gray-100 pb-4 mb-4">
                            <h3 className="font-semibold text-lg">Questions & Answers</h3>
                            <button onClick={addFaq} className="flex items-center gap-1.5 text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition-colors text-sm font-medium">
                                <Plus size={16} /> Add FAQ
                            </button>
                        </div>

                        <div className="space-y-4">
                            {config.faqs.map((faq, idx) => (
                                <div key={faq.id} className="p-4 bg-gray-50 border border-gray-200 rounded-xl relative group">
                                    <button onClick={() => removeFaq(idx)} className="absolute top-2 right-2 text-red-400 hover:text-red-600 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity p-1 bg-white rounded shadow-sm">
                                        <Trash2 size={16} />
                                    </button>
                                    <div className="mr-8">
                                        <label className="block text-xs font-semibold text-gray-600 mb-1">Question {idx + 1}</label>
                                        <input type="text" value={faq.question} onChange={(e) => handleFaqChange(idx, 'question', e.target.value)} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 mb-3 font-medium text-sm" />

                                        <label className="block text-xs font-semibold text-gray-600 mb-1">Answer</label>
                                        <textarea value={faq.answer} onChange={(e) => handleFaqChange(idx, 'answer', e.target.value)} rows={3} className="w-full p-2 border border-gray-300 rounded focus:border-blue-500 text-sm" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            <div className="fixed bottom-0 left-[280px] right-0 bg-white border-t border-gray-200 p-4 px-8 z-40 flex items-center justify-between shadow-[0_-4px_24px_rgba(0,0,0,0.02)]">
                <span className="text-sm text-gray-500 flex items-center gap-2">
                    {statusMessage && statusMessage.type === 'success' && <CheckCircle2 className="w-5 h-5 text-green-500" />}
                    {statusMessage?.text || 'Changes sync directly to Firestore.'}
                </span>
                <Button onClick={handleSave} disabled={saving} className="bg-primary-600 hover:bg-primary-700 text-white min-w-[120px]">
                    {saving ? 'Saving...' : 'Save Changes'}
                </Button>
            </div>
        </div>
    )
}

export default FAQManager

import React, { useState, useEffect } from 'react'
import { useLanguage } from '../../context/LanguageContext'
import { useFirestore } from '../../hooks/useFirestore'
import { uploadToCloudinary } from '../../utils/cloudinary'
import { doc, getDoc, setDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'
import { Plus, Edit, Trash2, Save, X, Star, Home, Compass, Map, Image as ImageIcon } from 'lucide-react'
import Button from '../UI/Button'
import Loading from '../UI/Loading'

const DEFAULT_SECTION_CONFIG = {
    eyebrow: 'DETAILED GUIDES TO OUR SERVICES',
    heading: 'Explore Our Consultation Guides',
    highlightedHeading: 'Consultation Guides',
    description: 'Detailed guides to help visitors understand consultation services.',
    background: {
        url: '',
        alt: '',
        bgSize: 'cover',
        bgRepeat: 'no-repeat',
        bgPosition: 'center'
    },
    bgOverlay: 'Light',
    bgPosition: 'Center',
    celestialDecoration: true,
    sectionEnabled: true
}

const GuidesManager = () => {
    const { isHindi } = useLanguage()
    const { documents: allGuides, addDocument, updateDocument, deleteDocument, loading } = useFirestore('services')
    const [editingGuide, setEditingGuide] = useState(null)
    const [showForm, setShowForm] = useState(false)

    // Section Config State
    const [sectionConfig, setSectionConfig] = useState(DEFAULT_SECTION_CONFIG)
    const [savingConfig, setSavingConfig] = useState(false)
    const [uploadingBg, setUploadingBg] = useState(false)

    // Form Data for individual guide
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        image: '',
        imageAlt: '',
        imagePosition: 'Center',
        icon: 'star',
        buttonLabel: 'View E-Brochure',
        buttonUrl: '',
        sortOrder: 0,
        enabled: true,
    })
    const [uploadingGuideImg, setUploadingGuideImg] = useState(false)

    const guidesList = allGuides.filter(s => s.type === 'guide').sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0))

    const DEFAULT_GUIDES = [
        { id: 'default1', title: 'Astrology Consultation (Default)', description: 'Explore detailed astrology consultation services, areas of guidance and more.', image: '', icon: 'star', buttonLabel: 'View E-Brochure', buttonUrl: '/brochure/astrology', sortOrder: 1, isDefault: true },
        { id: 'default2', title: 'Vastu Consultation (Default)', description: 'Discover Vastu consultation and planning services for homes, offices and more.', image: '', icon: 'home', buttonLabel: 'View E-Brochure', buttonUrl: '/brochure/vastu', sortOrder: 2, isDefault: true }
    ]
    const displayGuides = guidesList.length > 0 ? guidesList : DEFAULT_GUIDES;

    const icons = [
        { value: 'star', label: 'Star / Astrology', icon: Star },
        { value: 'home', label: 'Home / Vastu', icon: Home },
        { value: 'compass', label: 'Compass', icon: Compass },
        { value: 'map', label: 'Map', icon: Map }
    ]

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'guides_config')
                const snap = await getDoc(docRef)
                if (snap.exists()) {
                    setSectionConfig({ ...DEFAULT_SECTION_CONFIG, ...snap.data() })
                }
            } catch (err) {
                console.error("Failed to load config", err)
            }
        }
        fetchConfig()
    }, [])

    const handleSaveSectionConfig = async () => {
        setSavingConfig(true)
        try {
            await setDoc(doc(db, 'services', 'guides_config'), sectionConfig, { merge: true })
            alert('Section Configuration Saved!')
        } catch (error) {
            console.error('Error saving config:', error)
            alert('Failed to save config')
        } finally {
            setSavingConfig(false)
        }
    }

    const handleBgUpload = async (e) => {
        const file = e.target.files[0]
        if (!file) return
        try {
            setUploadingBg(true)
            const result = await uploadToCloudinary(file)
            if (result.success) {
                setSectionConfig(prev => ({ ...prev, background: { ...prev.background, url: result.url } }))
            }
        } catch (error) {
            console.error('Upload failed:', error)
            alert('Image upload failed.')
        } finally {
            setUploadingBg(false)
        }
    }

    const handleGuideImageUpload = async (e) => {
        const file = e.target.files[0]
        if (!file) return
        try {
            setUploadingGuideImg(true)
            const result = await uploadToCloudinary(file)
            if (result.success) {
                setFormData(prev => ({ ...prev, image: result.url }))
            }
        } catch (error) {
            console.error('Upload failed:', error)
            alert('Image upload failed.')
        } finally {
            setUploadingGuideImg(false)
        }
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        const guideData = { ...formData, type: 'guide', updatedAt: new Date() }
        let result
        if (editingGuide && editingGuide.id) {
            result = await updateDocument(editingGuide.id, guideData)
        } else {
            result = await addDocument({ ...guideData, createdAt: new Date() })
        }

        if (result?.error) {
            alert('Failed to save guide: ' + result.error)
            return
        }
        resetForm()
    }

    const handleEdit = (guide) => {
        setEditingGuide(guide)
        setFormData({
            title: guide.title || '',
            description: guide.description || '',
            image: guide.image || '',
            imageAlt: guide.imageAlt || '',
            imagePosition: guide.imagePosition || 'Center',
            icon: guide.icon || 'star',
            buttonLabel: guide.buttonLabel || 'View E-Brochure',
            buttonUrl: guide.buttonUrl || '',
            sortOrder: guide.sortOrder || 0,
            enabled: guide.enabled !== false,
        })
        setShowForm(true)
    }

    const handleDelete = async (guideId) => {
        if (window.confirm('Are you sure you want to delete this guide?')) {
            await deleteDocument(guideId)
        }
    }

    const resetForm = () => {
        setFormData({
            title: '', description: '', image: '', imageAlt: '', imagePosition: 'Center', icon: 'star',
            buttonLabel: 'View E-Brochure', buttonUrl: '', sortOrder: guidesList.length + 1, enabled: true
        })
        setEditingGuide(null)
        setShowForm(false)
    }

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <div className="flex items-center justify-between">
                <h1 className="text-2xl font-bold text-gray-900">Consultation Guides Manager</h1>
            </div>

            {/* SECTION CONFIGURATION */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-bold text-gray-800">Section Header & Background</h2>
                    <label className="flex items-center space-x-3 cursor-pointer">
                        <span className="text-sm font-medium text-gray-700">Enable Section</span>
                        <div className="relative">
                            <input type="checkbox" className="sr-only" checked={sectionConfig.sectionEnabled} onChange={(e) => setSectionConfig(prev => ({ ...prev, sectionEnabled: e.target.checked }))} />
                            <div className={`block w-10 h-6 rounded-full transition-colors ${sectionConfig.sectionEnabled ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                            <div className={`absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform ${sectionConfig.sectionEnabled ? 'translate-x-4' : ''}`}></div>
                        </div>
                    </label>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    {/* Background Settings */}
                    <div className="space-y-5">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">Background Image</label>
                            <div className="flex items-start space-x-4">
                                {sectionConfig.background?.url ? (
                                    <div className="relative w-32 h-24 rounded-lg overflow-hidden border border-gray-200">
                                        <img src={sectionConfig.background.url} alt="Background Preview" className="w-full h-full object-cover" />
                                        <button onClick={() => setSectionConfig(prev => ({ ...prev, background: { ...prev.background, url: '' } }))} className="absolute top-1 right-1 bg-white/90 p-1 rounded-md text-red-500 hover:bg-white shadow"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                ) : (
                                    <div className="w-32 h-24 bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center"><ImageIcon className="w-8 h-8 text-gray-400" /></div>
                                )}
                                <div className="flex-1">
                                    <input type="file" id="bg-upload" className="hidden" accept="image/*" onChange={handleBgUpload} disabled={uploadingBg} />
                                    <label htmlFor="bg-upload" className="inline-flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-lg cursor-pointer bg-white hover:bg-gray-50 text-sm font-medium">
                                        {uploadingBg ? <Loading type="spinner" size="sm" /> : <ImageIcon className="w-4 h-4" />}
                                        <span>Upload Image</span>
                                    </label>
                                </div>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4 mt-4">
                            <div>
                                <label className="block text-xs font-semibold text-gray-700 mb-1">BG Size</label>
                                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-gray-50" value={sectionConfig.background?.bgSize || 'cover'} onChange={e => setSectionConfig(prev => ({ ...prev, background: { ...prev.background, bgSize: e.target.value } }))}>
                                    <option value="cover">Cover (Fill)</option>
                                    <option value="contain">Contain (Fit)</option>
                                    <option value="auto">Auto (Original)</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-gray-700 mb-1">BG Repeat</label>
                                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-gray-50" value={sectionConfig.background?.bgRepeat || 'no-repeat'} onChange={e => setSectionConfig(prev => ({ ...prev, background: { ...prev.background, bgRepeat: e.target.value } }))}>
                                    <option value="no-repeat">No Repeat</option>
                                    <option value="repeat">Repeat Both</option>
                                    <option value="repeat-x">Repeat Horizontal</option>
                                    <option value="repeat-y">Repeat Vertical</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-gray-700 mb-1">BG Position</label>
                                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-gray-50" value={sectionConfig.background?.bgPosition || 'center'} onChange={e => setSectionConfig(prev => ({ ...prev, background: { ...prev.background, bgPosition: e.target.value } }))}>
                                    <option value="center">Center</option>
                                    <option value="top">Top</option>
                                    <option value="bottom">Bottom</option>
                                    <option value="left">Left</option>
                                    <option value="right">Right</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-gray-700 mb-1">Background Overlay</label>
                                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-gray-50" value={sectionConfig.bgOverlay} onChange={e => setSectionConfig({ ...sectionConfig, bgOverlay: e.target.value })}>
                                    <option value="Light">Light</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Strong">Strong</option>
                                </select>
                            </div>
                        </div>
                        <label className="flex items-center space-x-2 mt-4 cursor-pointer">
                            <input type="checkbox" checked={sectionConfig.celestialDecoration} onChange={(e) => setSectionConfig({ ...sectionConfig, celestialDecoration: e.target.checked })} className="rounded border-gray-300 text-[#a67828] focus:ring-[#a67828]" />
                            <span className="text-sm font-medium text-gray-700">Enable Celestial Orbit Decoration</span>
                        </label>
                    </div>
                    {/* Text Settings */}
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Eyebrow Text</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={sectionConfig.eyebrow} onChange={e => setSectionConfig({ ...sectionConfig, eyebrow: e.target.value })} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Main Heading</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={sectionConfig.heading} onChange={e => setSectionConfig({ ...sectionConfig, heading: e.target.value })} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Heading Highlight</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={sectionConfig.highlightedHeading} onChange={e => setSectionConfig({ ...sectionConfig, highlightedHeading: e.target.value })} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                            <textarea className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" rows="2" value={sectionConfig.description} onChange={e => setSectionConfig({ ...sectionConfig, description: e.target.value })} />
                        </div>
                    </div>
                </div>
                <div className="fixed bottom-0 left-[280px] right-0 bg-white border-t border-gray-200 p-4 px-8 z-40 flex items-center justify-between shadow-[0_-4px_24px_rgba(0,0,0,0.02)]">
                    <span className="text-sm text-gray-600">Save changes to publish them to the live site.</span>
                    <Button onClick={handleSaveSectionConfig} disabled={savingConfig} className="bg-[#a67828] hover:bg-[#8C641C] text-white">
                        {savingConfig ? 'Saving...' : 'Save Section Config'}
                    </Button>
                </div>
            </div>

            {/* GUIDES LIST */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-bold text-gray-800">Manage Guide Cards</h2>
                    {!showForm && <Button onClick={() => { resetForm(); setShowForm(true) }} className="bg-[#a67828] hover:bg-[#8C641C] text-white px-4"><Plus className="w-4 h-4 mr-2" />Add Guide</Button>}
                </div>

                {showForm ? (
                    <div className="bg-gray-50 border border-gray-200 rounded-xl p-6 mb-8">
                        <div className="flex justify-between items-center mb-6 border-b border-gray-200 pb-4">
                            <h3 className="text-lg font-bold text-gray-800">{editingGuide ? 'Edit Guide' : 'Create New Guide'}</h3>
                            <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-red-500"><X className="w-5 h-5" /></button>
                        </div>
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="grid md:grid-cols-2 gap-6">
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-1">Guide Title *</label>
                                        <input type="text" required value={formData.title} onChange={e => setFormData({ ...formData, title: e.target.value })} className="w-full px-4 py-2 border border-gray-300 rounded-lg" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-1">Description *</label>
                                        <textarea required rows="3" value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} className="w-full px-4 py-2 border border-gray-300 rounded-lg" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-700 mb-2">Card Full Background Image *</label>
                                        <div className="flex items-start space-x-4">
                                            {formData.image ? (
                                                <div className="relative w-32 h-32 rounded-lg overflow-hidden border border-gray-200">
                                                    <img src={formData.image} alt="Preview" className="w-full h-full object-cover" />
                                                    <button type="button" onClick={() => setFormData({ ...formData, image: '' })} className="absolute top-1 right-1 bg-white/90 p-1 rounded-md text-red-500 shadow"><Trash2 className="w-4 h-4" /></button>
                                                </div>
                                            ) : (
                                                <div className="w-32 h-32 bg-gray-100 border-2 border-dashed border-gray-300 rounded-lg flex justify-center items-center"><ImageIcon className="w-8 h-8 text-gray-400" /></div>
                                            )}
                                            <div className="flex-1">
                                                <input type="file" id="guide-img" className="hidden" accept="image/*" onChange={handleGuideImageUpload} />
                                                <label htmlFor="guide-img" className="inline-flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-lg cursor-pointer bg-white text-sm font-medium">
                                                    {uploadingGuideImg ? <Loading type="spinner" size="sm" /> : <ImageIcon className="w-4 h-4" />}
                                                    <span>Upload Image</span>
                                                </label>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-4">
                                    <div className="grid grid-cols-2 gap-4">
                                        <div><label className="block text-sm font-bold mb-1">Image Position</label>
                                            <select value={formData.imagePosition} onChange={e => setFormData({ ...formData, imagePosition: e.target.value })} className="w-full px-4 py-2 border rounded-lg"><option>Center</option><option>Top</option><option>Bottom</option></select></div>
                                        <div><label className="block text-sm font-bold mb-1">Card Icon</label>
                                            <select value={formData.icon} onChange={e => setFormData({ ...formData, icon: e.target.value })} className="w-full px-4 py-2 border rounded-lg">{icons.map(ic => <option key={ic.value} value={ic.value}>{ic.label}</option>)}</select></div>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div><label className="block text-sm font-bold mb-1">Button text</label>
                                            <input type="text" value={formData.buttonLabel} onChange={e => setFormData({ ...formData, buttonLabel: e.target.value })} className="w-full px-4 py-2 border rounded-lg" /></div>
                                        <div><label className="block text-sm font-bold mb-1">Button URL</label>
                                            <input type="text" value={formData.buttonUrl} onChange={e => setFormData({ ...formData, buttonUrl: e.target.value })} className="w-full px-4 py-2 border rounded-lg" /></div>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold mb-1">Sort Order</label>
                                        <input type="number" value={formData.sortOrder} onChange={e => setFormData({ ...formData, sortOrder: parseInt(e.target.value) || 0 })} className="w-full px-4 py-2 border rounded-lg" />
                                    </div>
                                    <label className="flex items-center space-x-2 mt-4 cursor-pointer">
                                        <input type="checkbox" checked={formData.enabled} onChange={e => setFormData({ ...formData, enabled: e.target.checked })} className="rounded text-[#a67828] w-4 h-4" />
                                        <span className="text-sm font-bold text-gray-700">Guide Visible</span>
                                    </label>
                                </div>
                            </div>
                            <div className="flex justify-end pt-4 space-x-3 border-t">
                                <Button type="button" variant="outline" onClick={() => setShowForm(false)}>Cancel</Button>
                                <Button type="submit" className="bg-[#a67828] hover:bg-[#8C641C] text-white">Save Guide</Button>
                            </div>
                        </form>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {loading ? <Loading type="dots" /> : displayGuides.map(guide => (
                            <div key={guide.id} className={`border rounded-xl  overflow-hidden relative ${guide.enabled !== false ? 'bg-white' : 'opacity-50'} ${guide.isDefault ? 'border-dashed border-2 border-[#D7B878] bg-[#FBF8F1]' : ''}`}>
                                <div className="h-40 bg-gray-100 relative group">
                                    {guide.image ? (
                                        <img src={guide.image} className="w-full h-full object-cover" alt="" />
                                    ) : (
                                        <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 bg-gray-50 border-b border-gray-100">
                                            <ImageIcon className="w-8 h-8 mb-2 opacity-50" />
                                            <span className="text-xs font-semibold">No Background Assigned</span>
                                        </div>
                                    )}
                                    <div className="absolute top-3 right-3 flex space-x-2">
                                        {guide.isDefault ? (
                                            <button onClick={() => handleEdit({ ...guide, id: null, isDefault: false, title: guide.title.replace(' (Default)', '') })} className="bg-[#a67828] hover:bg-[#8C641C] text-white px-4 py-1.5 rounded-lg shadow-sm text-xs font-bold uppercase tracking-wider transition-colors">Start Customizing</button>
                                        ) : (
                                            <>
                                                <button onClick={() => handleEdit(guide)} className="bg-white/90 backdrop-blur-sm p-2 rounded-lg shadow-sm text-[#a67828] hover:bg-[#a67828] hover:text-white transition-colors"><Edit className="w-4 h-4" /></button>
                                                <button onClick={() => handleDelete(guide.id)} className="bg-white/90 backdrop-blur-sm p-2 rounded-lg shadow-sm text-red-600 hover:bg-red-600 hover:text-white transition-colors"><Trash2 className="w-4 h-4" /></button>
                                            </>
                                        )}
                                    </div>
                                </div>
                                <div className="p-5">
                                    <h3 className="font-bold text-lg text-gray-900 border-b border-gray-100 pb-3 mb-3 break-words">{guide.title}</h3>
                                    <p className="text-sm text-gray-600 line-clamp-3 leading-relaxed">{guide.description}</p>
                                    {guide.isDefault && (
                                        <div className="mt-4 p-3 bg-[#FFFDF8] border border-[#E8DCC4] rounded-lg">
                                            <p className="text-xs text-[#8C641C] font-semibold leading-relaxed">
                                                This is a frontend placeholder. Click "Start Customizing" above to upload images and permanently save it to your database.
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    )
}

export default GuidesManager

import React, { useState, useEffect } from 'react'
import { doc, getDoc, setDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'
import { uploadToCloudinary } from '../../utils/cloudinary'
import Button from '../UI/Button'
import { Plus, Trash2, Edit, Image as ImageIcon } from 'lucide-react'
import Loading from '../UI/Loading'

const DEFAULT_PROCESS_CONFIG = {
    sectionEnabled: true,
    eyebrow: 'A SIMPLE AND SUPPORTIVE PROCESS',
    heading: 'Your Consultation Journey',
    buttonText: 'Start Your Consultation',
    background: {
        url: '',
        position: 'center',
        size: 'cover',
        repeat: 'no-repeat'
    },
    bgOverlay: 'Light',
    steps: [
        { id: '1', number: '01', title: 'Choose a Service', description: 'Select the consultation that best suits your needs.' },
        { id: '2', number: '02', title: 'Share Your Details', description: 'Provide the relevant information and preferred consultation method.' },
        { id: '3', number: '03', title: 'Consultation', description: 'Discuss your questions and circumstances with personalised guidance.' },
        { id: '4', number: '04', title: 'Guidance & Next Steps', description: 'Receive practical and meaningful insights for your journey ahead.' }
    ]
}

const ProcessManager = () => {
    const [config, setConfig] = useState(DEFAULT_PROCESS_CONFIG)
    const [loading, setLoading] = useState(true)
    const [saving, setSaving] = useState(false)
    const [uploadingBg, setUploadingBg] = useState(false)

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'process_config')
                const snap = await getDoc(docRef)
                if (snap.exists()) {
                    setConfig({ ...DEFAULT_PROCESS_CONFIG, ...snap.data() })
                }
            } catch (err) {
                console.error("Failed to load config", err)
            } finally {
                setLoading(false)
            }
        }
        fetchConfig()
    }, [])

    const handleSave = async () => {
        setSaving(true)
        try {
            await setDoc(doc(db, 'services', 'process_config'), config)
            alert('Process Configuration Saved Successfully!')
        } catch (error) {
            console.error('Error saving config:', error)
            alert('Failed to save config')
        } finally {
            setSaving(false)
        }
    }

    const handleBgUpload = async (e) => {
        const file = e.target.files[0]
        if (!file) return
        try {
            setUploadingBg(true)
            const result = await uploadToCloudinary(file)
            if (result.success) {
                setConfig(prev => ({ ...prev, background: { ...prev.background, url: result.url } }))
            }
        } catch (error) {
            alert('Image upload failed.')
        } finally {
            setUploadingBg(false)
        }
    }

    const handleAddStep = () => {
        const newStep = {
            id: Date.now().toString(),
            number: `0${config.steps.length + 1}`.slice(-2),
            title: 'New Step Title',
            description: 'Step description text goes here.'
        }
        setConfig(prev => ({ ...prev, steps: [...prev.steps, newStep] }))
    }

    const handleUpdateStep = (index, field, value) => {
        const newSteps = [...config.steps]
        newSteps[index][field] = value
        setConfig(prev => ({ ...prev, steps: newSteps }))
    }

    const handleRemoveStep = (index) => {
        const newSteps = config.steps.filter((_, i) => i !== index)
        // Renumber remaining elements dynamically
        const renumbered = newSteps.map((step, idx) => ({ ...step, number: `0${idx + 1}`.slice(-2) }))
        setConfig(prev => ({ ...prev, steps: renumbered }))
    }

    if (loading) return <div className="p-10 flex justify-center"><Loading type="spinner" /></div>

    return (
        <div className="space-y-6 animate-fade-in pb-24">
            <h1 className="text-2xl font-bold text-gray-900">Consultation Journey Manager</h1>

            {/* Header & Background Settings */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-bold text-gray-800">Heading & Background</h2>
                    <label className="flex items-center space-x-3 cursor-pointer">
                        <span className="text-sm font-medium text-gray-700">Enable Section</span>
                        <div className="relative">
                            <input type="checkbox" className="sr-only" checked={config.sectionEnabled} onChange={(e) => setConfig(prev => ({ ...prev, sectionEnabled: e.target.checked }))} />
                            <div className={`block w-10 h-6 rounded-full transition-colors ${config.sectionEnabled ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                            <div className={`absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform ${config.sectionEnabled ? 'translate-x-4' : ''}`}></div>
                        </div>
                    </label>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Eyebrow Text</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={config.eyebrow} onChange={e => setConfig({ ...config, eyebrow: e.target.value })} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Main Heading</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={config.heading} onChange={e => setConfig({ ...config, heading: e.target.value })} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">CTA Button Text</label>
                            <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={config.buttonText} onChange={e => setConfig({ ...config, buttonText: e.target.value })} />
                        </div>
                    </div>

                    <div className="space-y-5">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">Section Background Image (Optional)</label>
                            <div className="flex items-start space-x-4">
                                {config.background?.url ? (
                                    <div className="relative w-32 h-24 rounded-lg overflow-hidden border border-gray-200">
                                        <img src={config.background.url} alt="Preview" className="w-full h-full object-cover" />
                                        <button onClick={() => setConfig(prev => ({ ...prev, background: { ...prev.background, url: '' } }))} className="absolute top-1 right-1 bg-white/90 p-1 rounded-md text-red-500 hover:bg-white shadow"><Trash2 className="w-4 h-4" /></button>
                                    </div>
                                ) : (
                                    <div className="w-32 h-24 bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center"><ImageIcon className="w-8 h-8 text-gray-400" /></div>
                                )}
                                <div className="flex-1">
                                    <input type="file" id="process-bg-upload" className="hidden" accept="image/*" onChange={handleBgUpload} />
                                    <label htmlFor="process-bg-upload" className="inline-flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-lg cursor-pointer bg-white hover:bg-gray-50 text-sm font-medium">
                                        {uploadingBg ? <Loading type="spinner" size="sm" /> : <ImageIcon className="w-4 h-4" />}
                                        <span>Upload Image</span>
                                    </label>
                                </div>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-semibold text-gray-700 mb-1">Background Overlay</label>
                                <select className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm" value={config.bgOverlay} onChange={e => setConfig({ ...config, bgOverlay: e.target.value })}>
                                    <option value="None">None</option>
                                    <option value="Light">Light</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Strong">Strong</option>
                                </select>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Timeline Steps Editor */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                <div className="flex items-center justify-between mb-6">
                    <h2 className="text-lg font-bold text-gray-800">Process Steps</h2>
                    <Button onClick={handleAddStep} className="bg-blue-50 text-blue-600 hover:bg-blue-100"><Plus className="w-4 h-4 mr-2" />Add Step</Button>
                </div>

                <div className="space-y-4">
                    {config.steps.map((step, index) => (
                        <div key={index} className="flex gap-4 p-4 border border-gray-200 rounded-xl bg-gray-50 items-start">
                            <div className="w-[40px] h-[40px] rounded-full bg-[#D7B878] text-white flex items-center justify-center font-bold shrink-0">{step.number}</div>
                            <div className="flex-1 space-y-3">
                                <div>
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Step Title</label>
                                    <input type="text" className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm bg-white" value={step.title} onChange={(e) => handleUpdateStep(index, 'title', e.target.value)} />
                                </div>
                                <div>
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Description</label>
                                    <textarea className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm bg-white" rows="2" value={step.description} onChange={(e) => handleUpdateStep(index, 'description', e.target.value)} />
                                </div>
                            </div>
                            <button onClick={() => handleRemoveStep(index)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg shrink-0 mt-6"><Trash2 className="w-4 h-4" /></button>
                        </div>
                    ))}
                </div>
            </div>

            <div className="fixed bottom-0 left-[280px] right-0 bg-white border-t border-gray-200 p-4 px-8 z-40 flex items-center justify-between shadow-[0_-4px_24px_rgba(0,0,0,0.02)]">
                <span className="text-sm text-gray-600">Save changes to push them live immediately.</span>
                <Button onClick={handleSave} disabled={saving} className="bg-[#a67828] hover:bg-[#8C641C] text-white">
                    {saving ? 'Saving Config...' : 'Save Process Config'}
                </Button>
            </div>
        </div>
    )
}

export default ProcessManager

import React, { useState } from 'react'
import { Image as ImageIcon, Trash2 } from 'lucide-react'
import { uploadToCloudinary } from '../../utils/cloudinary'
import Loading from '../UI/Loading'

const SectionStyleEditor = ({ styleConfig, setStyleConfig, label = "Section Styling" }) => {
    const [uploadingBg, setUploadingBg] = useState(false)

    // Helper to safely update nested properties
    const updateStyle = (field, value) => {
        setStyleConfig(prev => ({
            ...prev,
            [field]: value
        }))
    }

    const updateNestedStyle = (parent, field, value) => {
        setStyleConfig(prev => ({
            ...prev,
            [parent]: {
                ...prev[parent],
                [field]: value
            }
        }))
    }

    const handleBgUpload = async (e) => {
        const file = e.target.files[0]
        if (!file) return
        try {
            setUploadingBg(true)
            const result = await uploadToCloudinary(file)
            if (result.success) {
                updateNestedStyle('bgImage', 'url', result.url)
            }
        } catch (error) {
            alert('Image upload failed.')
        } finally {
            setUploadingBg(false)
        }
    }

    return (
        <div className="bg-gray-50 border border-gray-200 rounded-xl p-5 mb-6">
            <h3 className="text-md font-bold text-gray-800 mb-4 border-b border-gray-200 pb-2">{label}</h3>

            {/* Base Configuration */}
            <div className="grid md:grid-cols-2 gap-6 mb-6">
                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">Background Type</label>
                    <div className="flex bg-white rounded-lg border border-gray-300 overflow-hidden">
                        {['color', 'gradient', 'image'].map(type => (
                            <button
                                key={type}
                                onClick={() => updateStyle('bgType', type)}
                                className={`flex-1 py-2 text-xs font-medium capitalize transition-colors ${styleConfig.bgType === type ? 'bg-primary-600 text-white' : 'hover:bg-gray-50 text-gray-700'}`}
                            >
                                {type}
                            </button>
                        ))}
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">Text Color Theme</label>
                    <div className="flex bg-white rounded-lg border border-gray-300 overflow-hidden">
                        <button
                            onClick={() => updateStyle('textTheme', 'dark')}
                            className={`flex-1 py-2 text-xs font-medium transition-colors ${styleConfig.textTheme === 'dark' ? 'bg-gray-800 text-white' : 'hover:bg-gray-50 text-gray-700'}`}
                        >
                            Dark Text (Black)
                        </button>
                        <button
                            onClick={() => updateStyle('textTheme', 'light')}
                            className={`flex-1 py-2 text-xs font-medium transition-colors ${styleConfig.textTheme === 'light' ? 'bg-gray-200 text-gray-900 border-l border-gray-300' : 'hover:bg-gray-50 text-gray-700 border-l border-gray-300'}`}
                        >
                            Light Text (White)
                        </button>
                    </div>
                </div>
            </div>

            {/* Solid Color Config */}
            {styleConfig.bgType === 'color' && (
                <div className="flex items-center space-x-4 mb-4">
                    <label className="block text-sm font-semibold text-gray-700">Solid Color:</label>
                    <input
                        type="color"
                        value={styleConfig.bgColor || '#ffffff'}
                        onChange={(e) => updateStyle('bgColor', e.target.value)}
                        className="w-12 h-10 p-1 border border-gray-300 rounded cursor-pointer"
                    />
                    <span className="text-xs text-gray-500 font-mono">{styleConfig.bgColor || '#ffffff'}</span>
                </div>
            )}

            {/* Gradient Config */}
            {styleConfig.bgType === 'gradient' && (
                <div className="grid grid-cols-3 gap-4 mb-4">
                    <div>
                        <label className="block text-xs font-semibold text-gray-700 mb-1">Start Color</label>
                        <input
                            type="color"
                            value={styleConfig.gradientColors?.start || '#FBF8F1'}
                            onChange={(e) => updateNestedStyle('gradientColors', 'start', e.target.value)}
                            className="w-full h-10 p-1 border border-gray-300 rounded cursor-pointer"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-gray-700 mb-1">End Color</label>
                        <input
                            type="color"
                            value={styleConfig.gradientColors?.end || '#FFFFFF'}
                            onChange={(e) => updateNestedStyle('gradientColors', 'end', e.target.value)}
                            className="w-full h-10 p-1 border border-gray-300 rounded cursor-pointer"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-gray-700 mb-1">Direction</label>
                        <select
                            value={styleConfig.gradientColors?.direction || '180deg'}
                            onChange={(e) => updateNestedStyle('gradientColors', 'direction', e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
                        >
                            <option value="180deg">Bottom (180&deg;)</option>
                            <option value="90deg">Right (90&deg;)</option>
                            <option value="135deg">Diagonal (135&deg;)</option>
                            <option value="0deg">Top (0&deg;)</option>
                            <option value="circle">Radial Focus (Circle)</option>
                        </select>
                    </div>
                </div>
            )}

            {/* Image Config */}
            {styleConfig.bgType === 'image' && (
                <div className="space-y-4">
                    <div className="flex items-start space-x-4">
                        {styleConfig.bgImage?.url ? (
                            <div className="relative w-32 h-24 rounded-lg overflow-hidden border border-gray-200 shrink-0">
                                <img src={styleConfig.bgImage.url} alt="Preview" className="w-full h-full object-cover" />
                                <button onClick={() => updateNestedStyle('bgImage', 'url', '')} className="absolute top-1 right-1 bg-white/90 p-1 rounded-md text-red-500 hover:bg-white shadow"><Trash2 className="w-4 h-4" /></button>
                            </div>
                        ) : (
                            <div className="w-32 h-24 bg-white border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center shrink-0"><ImageIcon className="w-8 h-8 text-gray-400" /></div>
                        )}
                        <div className="flex-1">
                            <input type="file" id={`bg-upload-${label.replace(/\s+/g, '')}`} className="hidden" accept="image/*" onChange={handleBgUpload} />
                            <label htmlFor={`bg-upload-${label.replace(/\s+/g, '')}`} className="inline-flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-lg cursor-pointer bg-white hover:bg-gray-50 text-sm font-medium mb-3">
                                {uploadingBg ? <Loading type="spinner" size="sm" /> : <ImageIcon className="w-4 h-4" />}
                                <span>Upload Background Image</span>
                            </label>

                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Background Size</label>
                                    <select value={styleConfig.bgImage?.size || 'cover'} onChange={(e) => updateNestedStyle('bgImage', 'size', e.target.value)} className="w-full px-2 py-1.5 border border-gray-300 rounded text-xs bg-white">
                                        <option value="cover">Cover (Fills Space)</option>
                                        <option value="contain">Contain (Fits inside)</option>
                                        <option value="auto">Auto (Original size)</option>
                                        <option value="100% 100%">Stretch (100% 100%)</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Position</label>
                                    <select value={styleConfig.bgImage?.position || 'center'} onChange={(e) => updateNestedStyle('bgImage', 'position', e.target.value)} className="w-full px-2 py-1.5 border border-gray-300 rounded text-xs bg-white">
                                        <option value="center">Center</option>
                                        <option value="top">Top</option>
                                        <option value="bottom">Bottom</option>
                                        <option value="left">Left</option>
                                        <option value="right">Right</option>
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="bg-white p-4 rounded-lg border border-gray-200">
                        <label className="flex items-center space-x-3 cursor-pointer mb-3">
                            <input
                                type="checkbox"
                                checked={styleConfig.overlay?.enabled || false}
                                onChange={(e) => updateNestedStyle('overlay', 'enabled', e.target.checked)}
                                className="w-4 h-4 text-primary-600 rounded border-gray-300"
                            />
                            <span className="text-sm font-medium text-gray-800">Enable Color Overlay (Darkens/Lightens Image)</span>
                        </label>

                        {styleConfig.overlay?.enabled && (
                            <div className="flex items-center space-x-6 pl-7">
                                <div>
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Overlay Color</label>
                                    <input
                                        type="color"
                                        value={styleConfig.overlay?.color || '#000000'}
                                        onChange={(e) => updateNestedStyle('overlay', 'color', e.target.value)}
                                        className="w-10 h-8 p-1 border border-gray-300 rounded cursor-pointer"
                                    />
                                </div>
                                <div className="flex-1 max-w-[200px]">
                                    <label className="block text-xs font-semibold text-gray-600 mb-1">Opacity: {styleConfig.overlay?.opacity || 0.5}</label>
                                    <input
                                        type="range"
                                        min="0" max="1" step="0.05"
                                        value={styleConfig.overlay?.opacity || 0.5}
                                        onChange={(e) => updateNestedStyle('overlay', 'opacity', parseFloat(e.target.value))}
                                        className="w-full"
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    )
}

