 <Loading type="dots" text={isHindi ? 'प्रशंसापत्र लोड हो रहे हैं...' : 'Loading testimonials...'} />
 ) : testimonials.length === 0 ? (
 <div className="text-center py-8 text-gray-500 ">
 {isHindi ? 'अभी तक कोई प्रशंसापत्र नहीं' : 'No testimonials yet'}
