import React, { useState, useEffect } from 'react'
import { doc, getDoc } from 'firebase/firestore'
import { db } from '../../utils/firebase'
import { Plus, Minus } from 'lucide-react'
import { Link } from 'react-router-dom'
import { useTheme } from '../../hooks/useTheme'

const DEFAULT_CONFIG = {
    sectionEnabled: true,
    eyebrow: 'HAVE QUESTIONS?',
    heading: 'Frequently \nAsked Questions',
    description: 'Find answers to common questions about our consultations, services and process.',
    buttonText: 'Contact Us',
    buttonUrl: '/contact',
    faqs: [
        { id: 'faq-1', question: 'What can I expect in a consultation?', answer: 'Our consultations provide deep insights into your current life path...' }
    ]
}

const FAQSection = () => {
    const [openId, setOpenId] = useState('faq-0')
    const { sectionStyle, textClass, overlayElement } = useTheme('faq')
    const [config, setConfig] = useState(DEFAULT_CONFIG)

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'faq_config')
                const snap = await getDoc(docRef)
                if (snap.exists()) {
                    setConfig({ ...DEFAULT_CONFIG, ...snap.data() })
                }
            } catch (err) {
                // keep defaults
            }
        }
        fetchConfig()
    }, [])

    if (config.sectionEnabled === false) return null;

    const headingLines = config.heading?.split('\\n').map(l => l.trim()).filter(Boolean) || []

    return (
        <section className={`section-pad relative bg-[var(--cream-100)] border-y border-[var(--border-warm)] ${textClass}`} style={sectionStyle}>
            {overlayElement}
            <div className={`container max-w-[1080px] relative z-10`}>

                <div className="grid md:grid-cols-12 gap-12 lg:gap-20">

                    {/* Left: Content */}
                    <div className="md:col-span-5 md:pr-4">
                        <p className={`eyebrow mb-[14px] uppercase font-semibold text-[11px] tracking-wider ${textClass.includes('white') ? 'text-gray-200' : 'text-[#A67828]'}`}>{config.eyebrow}</p>
                        <h2 className={`heading-lg font-serif mb-[16px] max-w-[320px] ${textClass}`}>
                            {headingLines.map((line, i) => <React.Fragment key={i}>{line}{i < headingLines.length - 1 && <br className="hidden md:block" />}</React.Fragment>)}
                        </h2>
                        <p className={`body-md mb-[32px] max-w-[360px] ${textClass.includes('white') ? 'text-gray-100' : 'text-[var(--charcoal-600)]'}`}>
                            {config.description}
                        </p>
                        {config.buttonText && (
                            <Link to={config.buttonUrl || "/contact"} className={`btn hidden md:inline-flex font-sans text-[12px] ${textClass.includes('white') ? 'bg-transparent text-white border border-white hover:bg-white hover:text-black hover:border-black' : 'btn-outline'}`}>
                                {config.buttonText} &rarr;
                            </Link>
                        )}
                    </div>

                    {/* Right: Accordion */}
                    <div className="md:col-span-7">
                        <div className={`border-t ${textClass.includes('white') ? 'border-white/20' : 'border-[#DED3C4]'}`}>
                            {config.faqs.map((faq) => {
                                const isOpen = openId === faq.id
                                return (
                                    <div key={faq.id} className={`border-b ${textClass.includes('white') ? 'border-white/20' : 'border-[#DED3C4]'}`}>
                                        <button
                                            onClick={() => setOpenId(isOpen ? null : faq.id)}
                                            className="w-full flex items-center justify-between text-left min-h-[52px] py-[16px] group"
                                        >
                                            <span className={`font-medium text-[14px] md:text-[15px] pr-8 transition-colors flex-1 ${isOpen ? 'text-[var(--gold-500)]' : textClass.includes('white') ? 'text-gray-100 group-hover:text-white' : 'text-[var(--charcoal-800)] group-hover:text-[var(--gold-400)]'}`}>
                                                {faq.question}
                                            </span>
                                            <span className={`shrink-0 ${textClass.includes('white') ? 'text-gray-300' : 'text-[var(--charcoal-300)]'}`}>
                                                {isOpen ? <Minus size={16} strokeWidth={2} /> : <Plus size={16} strokeWidth={2} />}
                                            </span>
                                        </button>

                                        <div
                                            className="overflow-hidden transition-all duration-300 ease-premium"
                                            style={{ maxHeight: isOpen ? '300px' : '0px', opacity: isOpen ? 1 : 0 }}
                                        >
                                            <p className={`text-[13px] pb-[20px] leading-relaxed ${textClass.includes('white') ? 'text-gray-300' : 'text-[var(--charcoal-600)]'}`}>
                                                {faq.answer}
                                            </p>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    </div>

                </div>

            </div>
        </section>
    )
}

export default FAQSection

import React, { useEffect, useRef, useState } from 'react';
import AstroBackground from '../UI/AstroBackground';
import { Eye, Scale, Sparkles, HeartHandshake, Star, Moon } from 'lucide-react';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../../utils/firebase';

const iconMap = { Eye, Scale, Sparkles, HeartHandshake, Star, Moon };

const DEFAULT_CONFIG = {
    sectionEnabled: true,
    eyebrow: 'ASTROLOGY • SPIRITUALITY • KNOWLEDGE',
    headingLine1: 'Different Perspectives.',
    headingLine2: 'One ',
    headingHighlight: 'Deeper Understanding.',
    description: 'Our approach brings together the wisdom of astrology, the balance of Vastu, and the depth of spiritual practices to help you navigate life with greater clarity, confidence and purpose.',
    cards: [
        { id: '1', title: 'Insight', desc: 'Understanding life patterns', icon: 'Eye', enabled: true },
        { id: '2', title: 'Balance', desc: 'Harmony in personal and living spaces', icon: 'Scale', enabled: true },
        { id: '3', title: 'Clarity', desc: 'Practical and meaningful guidance', icon: 'Sparkles', enabled: true },
        { id: '4', title: 'Growth', desc: 'Support for your unique journey', icon: 'HeartHandshake', enabled: true }
    ],
    celestialGraphics: true
};

const Philosophy = () => {
    const [isVisible, setIsVisible] = useState(false);
    const [config, setConfig] = useState(DEFAULT_CONFIG);
    const sectionRef = useRef(null);

    useEffect(() => {
        const fetchConfig = async () => {
            try {
                const docRef = doc(db, 'services', 'philosophy_config');
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setConfig(prev => ({ ...prev, ...docSnap.data() }));
                }
            } catch (err) {
                // Silently fallback to DEFAULT_CONFIG
            }
        };
        fetchConfig();
    }, []);

    useEffect(() => {
        if (config.sectionEnabled === false) return; // Don't observe if disabled

        const currentObserverRefTarget = sectionRef.current;
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                    observer.unobserve(entry.target);
                }
            },
            { threshold: 0.15 }
        );

        if (currentObserverRefTarget) {
            observer.observe(currentObserverRefTarget);
        }

        return () => {
            if (currentObserverRefTarget) observer.unobserve(currentObserverRefTarget);
        };
    }, [config.sectionEnabled]);

    if (config.sectionEnabled === false) return null;
    if (!config.headingLine1 && !config.headingLine2 && !config.description) return null;

    const sectionBgStyle = config.background?.url ? {
        backgroundImage: `url(${config.background.url})`,
        backgroundSize: config.background.bgSize || 'cover',
        backgroundRepeat: config.background.bgRepeat || 'no-repeat',
        backgroundPosition: config.background.bgPosition || 'center',
    } : {
        backgroundColor: 'var(--section-bg)',
    };

    const styles = {
        '--section-bg': '#FBF8F1',
        '--section-card': '#FFFDF8',
        '--text-primary': '#25221E',
        '--text-secondary': '#625B52',
        '--text-muted': '#8C8378',
        '--gold': '#B78325',
        '--gold-dark': '#8C641C',
        '--gold-light': '#D7B878',
        '--border': '#E8DDCB',
        '--decorative': '#D9C39A',
    };

    return (
        <section
            ref={sectionRef}
            className={`relative w-full overflow-hidden flex flex-col items-center transition-opacity duration-1000 ${isVisible ? 'opacity-100' : 'opacity-0'}`}
            style={{
                ...styles,
                ...sectionBgStyle,
                minHeight: '640px',
                paddingTop: '90px',
                paddingBottom: '80px',
            }}
        >
            {config.background?.url && (
                <div className="absolute inset-0 bg-[rgba(251,248,241,0)] z-[0] pointer-events-none"></div>
            )}

            <style>{`
        .philosophy-card {
           background-color: var(--section-card);
           border: 1px solid var(--border);
           border-radius: 16px;
          box-shadow: 0 12px 30px rgba(70,50,25,0.03);
          transition: transform 400ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 400ms cubic-bezier(0.4, 0, 0.2, 1);
          position: relative;
        }
        .philosophy-card:hover {
          transform: translateY(-8px);
          box-shadow: 0 24px 50px rgba(70,50,25,0.08);
        }
        .philosophy-card:hover .icon-container {
          color: var(--gold-dark);
          border-color: var(--gold);
        }
        
        .orbit-circle {
          position: absolute;
          border: 1px solid var(--gold-light);
