                : 'Contact admin to add the first testimonial'
              }
            </p>
          </div>
        )}
      </div>
    </section>
  )
}

export default Testimonials

import React, { createContext, useContext, useState, useEffect } from 'react'

const LanguageContext = createContext()

export const LanguageProvider = ({ children }) => {
  const [isHindi, setIsHindi] = useState(false)

  useEffect(() => {
    const savedLang = localStorage.getItem('language')
    if (savedLang) {
      setIsHindi(savedLang === 'hindi')
    }
  }, [])

  useEffect(() => {
    localStorage.setItem('language', isHindi ? 'hindi' : 'english')
  }, [isHindi])

  const toggleLanguage = () => setIsHindi(!isHindi)

  const content = {
    // Common translations
    home: isHindi ? 'होम' : 'Home',
    about: isHindi ? 'परिचय' : 'About',
    services: isHindi ? 'सेवाएं' : 'Services',
    blog: isHindi ? 'ब्लॉग' : 'Blog',
    contact: isHindi ? 'संपर्क' : 'Contact',
    // Add more translations as needed
  }

  return (
    <LanguageContext.Provider value={{ isHindi, toggleLanguage, content }}>
      {children}
    </LanguageContext.Provider>
  )
}

export const useLanguage = () => useContext(LanguageContext)

import React, { createContext, useContext, useState, useEffect } from 'react'

const PopupContext = createContext()

export const usePopup = () => {
  const context = useContext(PopupContext)
  if (!context) throw new Error('usePopup must be used within a PopupProvider')
  return context
}

export const PopupProvider = ({ children }) => {
  const [isPopupOpen, setIsPopupOpen] = useState(false)
  const [popupService, setPopupService] = useState(null)

  const openPopup = (serviceSlug = null) => {
    setPopupService(serviceSlug)
    setIsPopupOpen(true)
  }

  const closePopup = () => {
    setIsPopupOpen(false)
    setPopupService(null)
  }

  // Lock body scroll when popup is open
  useEffect(() => {
    if (isPopupOpen) {
      document.body.classList.add('modal-open')
    } else {
      document.body.classList.remove('modal-open')
    }
    return () => document.body.classList.remove('modal-open')
  }, [isPopupOpen])

  // Close on Escape key
  useEffect(() => {
    const handleKey = (e) => {
      if (e.key === 'Escape' && isPopupOpen) closePopup()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [isPopupOpen])

  return (
    <PopupContext.Provider value={{ isPopupOpen, openPopup, closePopup, popupService }}>
      {children}
    </PopupContext.Provider>
  )
}

